import{_ as t,o as a,c as o,a5 as s}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Apply Hashtag to a Post Draft","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/apply-hashtag-to-post/spec.md","filePath":"feature/content-task-workflow/apply-hashtag-to-post/spec.md"}'),i={name:"feature/content-task-workflow/apply-hashtag-to-post/spec.md"};function r(n,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="apply-hashtag-to-a-post-draft" tabindex="-1">Apply Hashtag to a Post Draft <a class="header-anchor" href="#apply-hashtag-to-a-post-draft" aria-label="Permalink to &quot;Apply Hashtag to a Post Draft&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.6.17</td></tr><tr><td>Feature</td><td>Apply Hashtag to Post</td></tr><tr><td>Status</td><td>Approved implementation scope for the existing Post draft editor</td></tr><tr><td>Roles</td><td>Creator using the Post draft editor</td></tr></tbody></table><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Let a Creator apply active hashtags from the current workspace collection to a Post draft. A hashtag created while editing must first be saved to that workspace collection with an explicit purpose. Applying or removing a hashtag in the draft must not alter other posts or rewrite old snapshots.</p><h2 id="scope-and-decisions" tabindex="-1">Scope and decisions <a class="header-anchor" href="#scope-and-decisions" aria-label="Permalink to &quot;Scope and decisions&quot;">​</a></h2><ul><li>The target is the Content Creator Post draft editor at <code>/workspaces/{workspaceId}/editor</code>, which persists through the existing Post draft API. This feature does not write to the separate collaborative Task editor or its Yjs document.</li><li>A hashtag selected from the collection is copied into the editor&#39;s Post hashtag list. The existing <code>SavePostRequest.hashtags</code> field and <code>PostDocument.hashtags</code> list are the persisted snapshot; no new Post-to-collection reference is stored.</li><li>The Hashtag Collection page offers “Apply to Post”; it opens a new Post draft with the chosen hashtag prefilled. It does not select or edit an existing Post because the current Post editor has no existing-draft loading flow.</li><li>A newly typed hashtag opens the existing Add dialog, requires the Creator to choose a non-required purpose, and is added to the collection before it is applied to the editor state. Add and Post draft save are separate operations; PostgreSQL and MongoDB do not share a transaction. If the later Post save fails, the added collection entry remains available for retry.</li><li>The current Post draft has no campaign link. Event-specific, required hashtags remain visible with their scope but cannot be applied to an unscoped draft.</li><li>Applying updates the draft editor and preview. Existing autosave/submit behavior persists the resulting string snapshot. It does not approve, publish, schedule, or bulk-apply to other Posts.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ol><li>The editor loads active hashtags from the current workspace and lets the Creator select multiple entries.</li><li>Search is workspace-scoped; removed or other-workspace entries cannot be selected.</li><li>Applying a selected entry immediately updates the editor preview and includes its display tag in the next saved Post draft.</li><li>Typing a new tag and pressing Enter opens Add Hashtag with the typed value and a purpose choice. Successful creation adds the entry to the collection and the Post editor; cancellation or failed creation does not add it to the editor.</li><li>A normalized duplicate is reused from the current collection and is not added twice to the Post.</li><li>“Apply to Post” on an ordinary collection entry opens a new draft editor with that tag prefilled.</li><li>Hashtag text saved on a Post remains unchanged if its collection entry is later removed or edited.</li><li>Event-specific required entries are not selectable without a campaign-linked Post; their campaign scope is explained in the UI.</li><li>Existing Creator/Manager Post draft save authorization and existing auto-save/submit flows remain in force. The collection-Apply controls are shown only for Creator members.</li><li>New labels are present in Vietnamese and English, and controls use existing theme tokens in light/dark mode.</li></ol><h2 id="existing-interfaces" tabindex="-1">Existing interfaces <a class="header-anchor" href="#existing-interfaces" aria-label="Permalink to &quot;Existing interfaces&quot;">​</a></h2><ul><li><code>GET /api/v1/workspaces/{workspaceId}/hashtags</code> supplies active collection entries.</li><li><code>POST /api/v1/workspaces/{workspaceId}/hashtags</code> creates a newly typed entry with its chosen purpose.</li><li><code>POST /api/v1/workspaces/{workspaceId}/posts</code> and <code>PATCH /api/v1/workspaces/{workspaceId}/posts/{postId}</code> persist the Post hashtag string snapshot through <code>SavePostRequest.hashtags</code>.</li></ul><p>No separate Apply endpoint or database migration is needed for this scope. Invalid or removed collection entries cannot be selected. The editor&#39;s existing draft save errors remain visible through its existing save/submit behavior.</p><h2 id="ui-and-accessibility" tabindex="-1">UI and accessibility <a class="header-anchor" href="#ui-and-accessibility" aria-label="Permalink to &quot;UI and accessibility&quot;">​</a></h2><p>The editor&#39;s hashtag area includes a searchable workspace collection picker, selected-tag chips, and the existing type-to-add interaction. The Add dialog shows purpose and errors. The collection entry action has an accessible label naming the hashtag. Loading, empty, failed, and campaign-scoped states are announced to assistive technology. All new copy is localized; controls remain keyboard operable and use light/dark semantic tokens.</p><h2 id="test-seam" tabindex="-1">Test seam <a class="header-anchor" href="#test-seam" aria-label="Permalink to &quot;Test seam&quot;">​</a></h2><p>The agreed public test seam is the visible collection/editor UI through the existing Post draft API. Tests verify selection, new-tag creation with purpose, and the hashtags submitted in the saved Post request; they do not assert private hook state.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><ul><li>Applying hashtags to the collaborative Yjs Task editor.</li><li>Selecting an existing Post from the collection, campaign association, required-tag validation, or changing Post save authorization.</li><li>Atomic commit or compensation across the independent PostgreSQL collection and MongoDB Post stores.</li><li>AI suggestions, approval, publishing, scheduling, and cross-Post application.</li></ul>',17)])])}const u=t(i,[["render",r]]);export{g as __pageData,u as default};
